LBL = {
    'client': ('Замовник', 'Client', 'Заказчик'),
    'type': ('Тип обʼєкта', 'Property type', 'Тип объекта'),
    'loc': ('Локація', 'Location', 'Локация'),
    'scope': ('Обсяг', 'Scope', 'Объем'),
}
def seo_title(li, title, brand):
    if li == 1:
        base = title if brand in title else f'{brand}: {title[0].lower() + title[1:]}'
        return base + ' — an improvision project'
    base = title if brand in title else f'{title} {brand}'
    return base + (' — проєкт improvision' if li == 0 else ' — проект improvision')

out = []
for i, p in enumerate(P):
    rec = {'slug': p['slug'], 'id': p['id'], 'menuindex': i, 'category': p['cat'], 'langs': []}
    for li, ctx in enumerate(('web', 'en', 'ru')):
        title, brand = p['title'][li], p['brand'][li]
        specs = [{'label': LBL['client'][li], 'value': brand}, {'label': LBL['type'][li], 'value': TYPE[p['type']][li]}]
        if p.get('loc'): specs.append({'label': LBL['loc'][li], 'value': p['loc'][li]})
        elif p.get('city'): specs.append({'label': LBL['loc'][li], 'value': p['city'][li]})
        if p.get('scope'): specs.append({'label': LBL['scope'][li], 'value': p['scope'][li]})
        off = (0, 1, 2)[li]
        tags = [{'title': TAG[s][li], 'link': str(s + off)} for s in p['tags']]
        gallery = [{'image': 'assets/img/photos/' + g[0], 'alt': g[1][li]} for g in p['gallery']]
        card = 'assets/img/photos/' + (p.get('card') or ('projects/%s-card.jpg' % p['slug']))
        rec['langs'].append({
            'ctx': ctx, 'pagetitle': title,
            'description': p['intro'][li],
            'introtext': p['intro'][li],
            'content': ''.join('<p>%s</p>' % t.replace('&', '&amp;') for t in p['content'][li]),
            'tv': {
                'brand': brand, 'city': (p.get('city') or ('', '', ''))[li], 'year': '', 'category': p['cat'],
                'card_image': card, 'card_image_alt': f'{brand} — {title}',
                'checklist': '\n'.join(p['check'][li]) if p.get('check') else '',
                'gallery': gallery, 'directions': tags, 'specs': specs,
                'seo_title': seo_title(li, title, brand),
                'og_title': '', 'og_description': p['intro'][li], 'og_image': '',
            },
        })
    rec['convert'] = [(g[0], g[2]) for g in p['gallery'] if len(g) > 2]
    rec['card_src'] = None if p.get('card') else p['gallery'][0][2]
    out.append(rec)
json.dump(out, open('data.json', 'w'), ensure_ascii=False, indent=1)
print(len(out), 'projects')
